#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt::init();

    let port: u16 = std::env::var("ROUTER_PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(4005); // Default to 4005 to preserve 4002

    let bind_addr: SocketAddr = format!("0.0.0.0:{}", port).parse()?;

    let shared_state: SharedState = Arc::new(AppState {
        router: RwLock::new(DynamicRouterState::new()),
        client: reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(30))
            .build()?,
    });

    // Spawn 15-minute discovery loop
    tokio::spawn(start_discovery_worker(shared_state.clone()));

