# Let's write a deterministic model of the real Rust Sovereign Router & Gateway Contract
# to prove every state transition, failure mode, and ensure ZERO synthetic 200 mocks.

class SovereignQuarantineState:
    """Dynamic model admission and quarantine state machine (not hardcoded)."""
    def __init__(self):
        self.quarantined_models = {} # model_id -> reason
        self.model_latencies = {}   # model_id -> list of float ms

    def record_failure(self, model_id: str, status_code: int, error_msg: str):
        if status_code in (401, 402, 403):
            # Auth or payment failure -> Immediate Quarantine
            self.quarantined_models[model_id] = f"AUTH_OR_PAYMENT_FAILURE ({status_code}): {error_msg}"
        elif status_code == 429:
            # Rate limit -> Temporary backoff quarantine
            self.quarantined_models[model_id] = f"RATE_LIMITED (429): {error_msg}"
        elif status_code >= 500:
            self.quarantined_models[model_id] = f"UPSTREAM_SERVER_ERROR ({status_code})"

    def record_success(self, model_id: str, latency_ms: float):
        if model_id in self.quarantined_models:
            del self.quarantined_models[model_id]
        if model_id not in self.model_latencies:
            self.model_latencies[model_id] = []
        self.model_latencies[model_id].append(latency_ms)

    def is_admissible(self, model_id: str) -> bool:
        return model_id not in self.quarantined_models

