// server.ts - Production Express Gateway (Zero-Mock Doctrine)
import express, { Request, Response } from "express";
import { GoogleGenAI } from "@google/genai";

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 3000;
const GEMINI_API_KEY = process.env.GEMINI_API_KEY;

// Fail initialization visibility if key is absent
if (!GEMINI_API_KEY) {
  console.warn("[CRITICAL] GEMINI_API_KEY is not set. Gateway will fail-fast with 503 on requests.");
}

const ai = GEMINI_API_KEY ? new GoogleGenAI({ apiKey: GEMINI_API_KEY }) : null;

app.get("/health", (req: Request, res: Response) => {
  res.status(200).json({
    status: "healthy",
    gateway: "argon-express",
    upstreamConfigured: Boolean(GEMINI_API_KEY)
  });
});

app.post("/api/gateway/complete", async (req: Request, res: Response) => {
  const startTime = Date.now();
  const { prompt, model } = req.body;

  if (!prompt) {
    return res.status(400).json({
      error: {
        code: "INVALID_REQUEST",
        message: "Missing required field: 'prompt'"
      }
    });
  }

  // 1. Fail-fast if API key is not configured (NO FAKE 200)
  if (!ai || !GEMINI_API_KEY) {
    return res.status(503).json({
      error: {
        code: "UPSTREAM_UNCONFIGURED",
        message: "GEMINI_API_KEY is not configured on this host. Service unavailable."
      },
      status: "failed",
      latencyMs: Date.now() - startTime
    });
  }

  // 2. Real upstream dispatch
  try {
    const targetModel = model || "gemini-2.5-flash";
    const response = await ai.models.generateContent({
      model: targetModel,
      contents: prompt,
    });

    const candidate = response.candidates?.[0];
    const textOutput = response.text || candidate?.content?.parts?.[0]?.text;

    if (!textOutput) {
      throw new Error("Upstream returned empty candidate payload.");
    }

    // Authentic 200 completion with genuine telemetry
    return res.status(200).json({
      status: "completed",
      apiSurface: "InteractionsAPI",
      interactionId: response.responseId || `gen-${Date.now()}`,
      model: targetModel,
      output: textOutput,
      latencyMs: Date.now() - startTime
    });

  } catch (err: any) {
    const latencyMs = Date.now() - startTime;
    console.error(`[GATEWAY ERROR] Upstream dispatch failure (${latencyMs}ms):`, err?.message || err);

    // 3. Strict 502 Bad Gateway on upstream failure (NO FAKE 200 / NO "[Verified Capability Dispatch]")
    return res.status(502).json({
      error: {
        code: "UPSTREAM_DISPATCH_FAILURE",
        message: err?.message || "Failed to communicate with upstream Gemini model.",
        upstreamStatus: err?.status || 502
      },
      status: "failed",
      latencyMs
    });
  }
});

app.listen(PORT, () => {
  console.log(`Argon Express Gateway actively listening on port ${PORT}`);
