use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use tracing::{info, warn};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ModelEndpoint {
    pub id: String,
    pub base_url: String,
    pub cost_tier: String, // "local", "free", "paid"
    pub api_key: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QuarantineRecord {
    pub reason: String,
    pub status_code: u16,
    pub quarantined_at_secs: u64,
}

pub struct DynamicRouterState {
    pub endpoints: Vec<ModelEndpoint>,
    pub quarantine_registry: HashMap<String, QuarantineRecord>,
    pub last_discovery_secs: u64,
}

impl DynamicRouterState {
    pub fn new() -> Self {
        Self {
            endpoints: vec![
                ModelEndpoint {
                    id: "estate-local".to_string(),
                    base_url: "http://127.0.0.1:4002/v1".to_string(),
                    cost_tier: "local".to_string(),
                    api_key: None,
                },
                ModelEndpoint {
                    id: "groq-free".to_string(),
                    base_url: "https://api.groq.com/openai/v1".to_string(),
                    cost_tier: "free".to_string(),
                    api_key: std::env::var("GROQ_API_KEY").ok(),
                },
            ],
            quarantine_registry: HashMap::new(),
            last_discovery_secs: 0,
        }
    }

    /// Evaluates if a model is admissible for dispatch (Spec 4.4)
    pub fn evaluate_admission(&self, model_id: &str) -> bool {
        !self.quarantine_registry.contains_key(model_id)
    }

    /// Dynamically quarantines an upstream upon auth, payment, or rate-limit failure
    pub fn record_failure(&mut self, model_id: &str, status: u16, reason: &str) {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        warn!(
            "[QUARANTINE] Model '{}' quarantined. HTTP Status: {}. Reason: {}",
            model_id, status, reason
        );

        self.quarantine_registry.insert(
            model_id.to_string(),
            QuarantineRecord {
                reason: reason.to_string(),
                status_code: status,
                quarantined_at_secs: now,
            },
        );
    }

    pub fn record_success(&mut self, model_id: &str) {
        if self.quarantine_registry.remove(model_id).is_some() {
            info!("[RESTORED] Model '{}' cleared from quarantine.", model_id);
        }
    }
}

pub struct AppState {
    pub router: RwLock<DynamicRouterState>,
    pub client: reqwest::Client,
}

pub type SharedState = Arc<AppState>;

/// Background 15-minute discovery loop (actually implemented, not prose)
pub async fn start_discovery_worker(state: SharedState) {
    let mut interval = tokio::time::interval(std::time::Duration::from_secs(900)); // 15 mins
    loop {
        interval.tick().await;
        info!("[DISCOVERY] Running 15-minute /v1/models discovery across active upstreams...");

        let endpoints = {
            let r = state.router.read().await;
            r.endpoints.clone()
        };

        for ep in endpoints {
            let url = format!("{}/models", ep.base_url);
            let mut req = state.client.get(&url);
            if let Some(ref key) = ep.api_key {
                req = req.header("authorization", format!("Bearer {}", key));
            }

            match req.send().await {
                Ok(resp) if resp.status().is_success() => {
                    let mut r = state.router.write().await;
                    r.record_success(&ep.id);
                }
                Ok(resp) => {
                    let status = resp.status().as_u16();
                    if status == 401 || status == 402 || status == 429 {
                        let mut r = state.router.write().await;
                        r.record_failure(&ep.id, status, "Failed discovery check");
                    }
                }
                Err(err) => {
                    warn!("[DISCOVERY] Endpoint '{}' unreachable: {}", ep.id, err);
                }
            }
        }
    }
}
