#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ModelEndpoint {
    pub id: String,
    pub base_url: String,
    pub cost_tier: String, // "local", "free", "paid"
    pub api_key: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QuarantineRecord {
    pub reason: String,
    pub status_code: u16,
    pub quarantined_at_secs: u64,
}

pub struct DynamicRouterState {
    pub endpoints: Vec<ModelEndpoint>,
    pub quarantine_registry: HashMap<String, QuarantineRecord>,
    pub last_discovery_secs: u64,
}

impl DynamicRouterState {
    pub fn new() -> Self {
        Self {
            endpoints: vec![
                ModelEndpoint {
                    id: "estate-local".to_string(),
                    base_url: "http://127.0.0.1:4002/v1".to_string(),
                    cost_tier: "local".to_string(),
                    api_key: None,
