            "quarantined_endpoints": quarantined,
        })),
    )
}

async fn models_handler(State(state): State<SharedState>) -> Response {
    let r = state.router.read().await;
    let available: Vec<&String> = r
        .endpoints
        .iter()
        .filter(|e| r.evaluate_admission(&e.id))
        .map(|e| &e.id)
        .collect();

    Json(json!({
        "object": "list",
        "data": available.iter().map(|id| json!({"id": id, "object": "model"})).collect::<Vec<_>>()
    }))
    .into_response()
}

async fn chat_completions_handler(
    State(state): State<SharedState>,
    headers: HeaderMap,
    Json(payload): Json<Value>,
) -> Response {
    let endpoints = {
        let r = state.router.read().await;
        r.endpoints.clone()
    };

    let mut last_error = "No admissible endpoints".to_string();

    for ep in endpoints {
        {
            let r = state.router.read().await;
            if !r.evaluate_admission(&ep.id) {
                continue;
            }
        }

        let target_url = format!("{}/chat/completions", ep.base_url);
        let mut req = state.client.post(&target_url).json(&payload);

        if let Some(auth) = headers.get("authorization") {
            req = req.header("authorization", auth);
        } else if let Some(ref key) = ep.api_key {
            req = req.header("authorization", format!("Bearer {}", key));
        }

        match req.send().await {
            Ok(resp) => {
                let status = resp.status();

                if status == StatusCode::UNAUTHORIZED
                    || status == StatusCode::PAYMENT_REQUIRED
                    || status == StatusCode::TOO_MANY_REQUESTS
                {
                    let reason = format!("Upstream returned status {}", status);
                    {
                        let mut r = state.router.write().await;
                        r.record_failure(&ep.id, status.as_u16(), &reason);
                    }
                    last_error = reason;
                    continue;
                }

                if status.is_server_error() {
                    warn!("Endpoint '{}' 5xx error. Failing over...", ep.id);
                    last_error = format!("Status {}", status);
                    continue;
                }

                if let Ok(body) = resp.json::<Value>().await {
                    let mut r = state.router.write().await;
                    r.record_success(&ep.id);
                    return (status, Json(body)).into_response();
                }
            }
            Err(e) => {
                warn!("Connection error on '{}': {}. Failing over...", ep.id, e);
                last_error = e.to_string();
                continue;
            }
        }
    }

    error!("[ROUTER EXHAUSTION] Cascade exhausted: {}", last_error);
    (
        StatusCode::BAD_GATEWAY,
        Json(json!({
            "error": {
                "code": "SOVEREIGN_CASCADE_EXHAUSTED",
                "message": format!("All admissible routing endpoints failed: {}", last_error)
            }
        })),
    )
        .into_response()
}
