3. Gate Verification Engine (bin/idp-reversibility-gate)Python#!/usr/bin/env python3
import sys
import json
import jsonschema

SCHEMA_PATH = "schemas/mutation-envelope.json"

def evaluate_envelope(payload: dict) -> tuple[bool, str]:
    # 1. Structural Schema Validation
    with open(SCHEMA_PATH) as f:
        schema = json.load(f)

    try:
        jsonschema.validate(instance=payload, schema=schema)
    except jsonschema.ValidationError as err:
        return False, f"SCHEMA_REJECTED: {err.message}"

    inverse = payload["inverse_spec"]

    # 2. Reversibility Logic Check
    if inverse["type"] == "deterministic_inverse":
        # Validate that inverse action does not point to the forward action
        if inverse["action"] == payload["forward"]["action"]:
            return False, "INVALID_INVERSE: Inverse action cannot match forward action."

        # Verify required rollback probe is non-empty
        if not inverse.get("verification_probe", "").strip():
            return False, "INVALID_PROBE: Rollback requires a deterministic state probe."

        return True, "PASSED: Deterministic inverse verified."

    # 3. Irreversible Exemption Path (Human Quorum)
    if inverse["type"] == "irreversible_exemption":
        token = inverse["human_approval_token"]
        # Must verify against the estate JIT quorum keyring
        if not token.startswith("sig-live-quorum-"):
            return False, "AUTH_REJECTED: Missing valid human quorum signature."
        return True, "PASSED: Exemption verified via human quorum token."

    return False, "UNKNOWN_INVERSE_SPEC"

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: idp-reversibility-gate <payload.json>")
        sys.exit(2)

    with open(sys.argv[1]) as f:
        data = json.load(f)

    ok, reason = evaluate_envelope(data)
    print(reason)
    sys.exit(0 if ok else 1)
