```python
#!/usr/bin/env python3
"""
idp-capability-collector — roll every repo's capability.yaml into registry.json.
Idempotent, deterministic, free-tier friendly.
"""
from __future__ import annotations
import argparse, json, os, subprocess, sys, hashlib
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

try:
    import yaml
    from jsonschema import Draft202012Validator
except ImportError:
    sys.exit("pip install pyyaml jsonschema")


SCHEMA_PATH = Path(__file__).resolve().parent.parent / "schemas" / "factory.contract.v1.json"
STATE_RANK = {"current": 0, "incubating": 1, "deprecated": 2}


def load_schema() -> Draft202012Validator:
    return Draft202012Validator(json.loads(SCHEMA_PATH.read_text()))


def discover_repos(explicit: list[str] | None) -> list[str]:
    if explicit:
        return explicit
    try:
        out = subprocess.check_output(
            ["gh", "repo", "list", "--limit", "200", "--json", "name", "-q", ".[].name"],
            text=True, timeout=30,
        )
        return [r.strip() for r in out.splitlines() if r.strip()]
    except Exception:
        # Fallback: scan sibling directories
        root = Path.cwd().parent
        return [p.name for p in root.iterdir() if (p / "capability.yaml").exists()]


def find_capability_yaml(repo: str, root: Path) -> Path | None:
    for candidate in [
        root / repo / "capability.yaml",
        root / repo / ".factory" / "capability.yaml",
    ]:
        if candidate.exists():
            return candidate
    # Try GitHub raw fetch (free tier: 60 req/hr unauthenticated, 5000 authed)
    try:
        url = f"https://raw.githubusercontent.com/chidionyema/{repo}/main/capability.yaml"
        out = subprocess.check_output(["curl", "-fsSL", url], text=True, timeout=10)
        tmp = Path(f"/tmp/{repo}.capability.yaml")
        tmp.write_text(out)
        return tmp
    except Exception:
        return None


def validate(validator: Draft202012Validator, data: dict, source: str) -> list[str]:
    errors = []
    for e in validator.iter_errors(data):
        errors.append(f"{source}: {'.'.join(str(p) for p in e.absolute_path)}: {e.message}")
    return errors


def stable_hash(obj: Any) -> str:
    return hashlib.sha256(json.dumps(obj, sort_keys=True).encode()).hexdigest()[:12]


def build_registry(repos: list[str], root: Path) -> dict:
    validator = load_schema()
    branches_out: list[dict] = []
    capabilities_out: list[dict] = []
    warnings: list[str] = []
    seed_repos: list[str] = []
    seen_cap_ids: dict[str, list[dict]] = {}

    for repo in repos:
        path = find_capability_yaml(repo, root)
        if path is None:
            warnings.append(f"NO_CAPABILITY_YAML: {repo}")
            continue
        try:
            raw = yaml.safe_load(path.read_text())
        except Exception as e:
            warnings.append(f"YAML_PARSE_ERROR: {repo}: {e}")
            continue
        if not isinstance(raw, dict):
            warnings.append(f"NOT_A_MAPPING: {repo}")
            continue
        errs = validate(validator, raw, repo)
        if errs:
            warnings.extend(f"SCHEMA: {e}" for e in errs)
            continue
        if raw["repo"]["name"] != repo:
            warnings.append(f"NAME_MISMATCH: dir={repo} yaml={raw['repo']['name']}")
            continue
        role = raw["repo"]["role"]
        if role == "seed-expression":
            seed_repos.append(repo)

        for branch in raw["branches"]:
            if not branch["grade"] or not branch["grade"][0].get("metric"):
                warnings.append(f"UNGRADED_BRANCH: {repo}:{branch['name']}")
                continue
            branches_out.append({
                "repo": repo,
                "branch": branch["name"],
                "state": branch["state"],
                "grade": branch["grade"],
                "since": branch["since"],
                "supersedes": branch.get("supersedes", []),
            })

        for cap in raw.get("capabilities", []):
            entry = {
                "id": cap["id"],
                "name": cap["name"],
                "class": cap["class"],
                "mode": cap["mode"],
                "scope": cap["scope"],
                "produces_again": cap.get("produces_again", False),
                "state": cap["state"],
                "source_repo": repo,
                "source_branch": next(
                    (b["name"] for b in raw["branches"]), "unknown"
                ),
                "grade": next(
                    (b["grade"] for b in raw["branches"]), []
                ),
                "since": raw["branches"][0]["since"],
            }
            capabilities_out.append(entry)
            seen_cap_ids.setdefault(cap["id"], []).append(entry)

    if len(seed_repos) > 1:
        warnings.append(f"MULTIPLE_SEEDS: {seed_repos} — refusing, no seed emitted")
        seed = ""
    elif seed_repos:
        seed = seed_repos[0]
    else:
        warnings.append("NO_SEED: no repo declares role: seed-expression")
        seed = ""

    for cap_id, entries in seen_cap_ids.items():
        current = [e for e in entries if e["state"] == "current"]
        if len(current) > 1:
            warnings.append(
                f"AMBIGUOUS_CURRENT: {cap_id} produced by "
                f"{[e['source_repo'] for e in current]}"
            )
        elif len(current) == 0 and len(entries) > 1:
            warnings.append(f"NO_CURRENT: {cap_id} exists only as incubating/deprecated")

    branches_out.sort(key=lambda b: (b["repo"], b["branch"]))
    capabilities_out.sort(key=lambda c: (c["id"], STATE_RANK.get(c["state"], 9), c["source_repo"]))

    return {
        "schema": "factory.registry/v1",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "seed_repo": seed,
        "branches": branches_out,
        "capabilities": capabilities_out,
        "warnings": warnings,
    }


def emit_sheds(prev: dict | None, curr: dict) -> list[dict]:
    if prev is None:
        return []
    sheds = []
    prev_index = {c["id"]: c for c in prev.get("capabilities", [])}
    for cap in curr["capabilities"]:
        old = prev_index.get(cap["id"])
        if old and old["state"] != "deprecated" and cap["state"] == "deprecated":
            sheds.append({
                "event": "shed",
                "at": curr["generated_at"],
                "capability_id": cap["id"],
                "source_repo": cap["source_repo"],
                "source_branch": cap["source_branch"],
                "superseded_by": cap.get("superseded_by", None),
            })
    return sheds


def append_ledger(sheds: list[dict], ledger_path: Path) -> None:
    if not sheds:
        return
    ledger_path.parent.mkdir(parents=True, exist_ok=True)
    with ledger_path.open("a") as f:
        for s in sheds:
            f.write(json.dumps(s, sort_keys=True) + "\n")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--repos", nargs="*", help="explicit repo names; omit to auto-discover")
    ap.add_argument("--root", default=".", help="parent directory containing repos")
    ap.add_argument("--out", default="registry.json")
    ap.add_argument("--prev", default=None, help="previous registry.json for shed detection")
    ap.add_argument("--ledger", default="ledger/sheds.ndjson")
    ap.add_argument("--strict", action="store_true", help="exit non-zero on any warning")
    args = ap.parse_args()

    root = Path(args.root).resolve()
    repos = discover_repos(args.repos)
    registry = build_registry(repos, root)

    out_path = Path(args.out)
    out_path.write_text(json.dumps(registry, indent=2, sort_keys=True) + "\n")

    prev = None
    if args.prev and Path(args.prev).exists():
        prev = json.loads(Path(args.prev).read_text())

    sheds = emit_sheds(prev, registry)
    append_ledger(sheds, Path(args.ledger))

    print(f"registry written: {out_path}")
    print(f"repos seen: {len(repos)}  branches: {len(registry['branches'])}  caps: {len(registry['capabilities'])}")
    print(f"warnings: {len(registry['warnings'])}  sheds: {len(sheds)}")
    for w in registry["warnings"]:
        print(f"  warn: {w}")

    if args.strict and registry["warnings"]:
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

