## 6. `bin/idp-resolve` — the resolver

```python
#!/usr/bin/env python3
"""
idp-resolve — bind an order's capability IDs to current branch outputs.
The moat, made mechanical.
"""
from __future__ import annotations
import argparse, json, sys
from datetime import datetime, timezone
from pathlib import Path

try:
    from jsonschema import Draft202012Validator
except ImportError:
    sys.exit("pip install jsonschema")


STATE_PRIORITY = {"current": 0, "incubating": 1, "deprecated": 2}


def load_json(p: str | Path) -> dict:
    return json.loads(Path(p).read_text())


def validate(validator: Draft202012Validator, data: dict, name: str) -> None:
    errors = sorted(validator.iter_errors(data), key=lambda e: e.path)
    if errors:
        for e in errors:
            print(f"{name}: {'.'.join(str(p) for p in e.absolute_path)}: {e.message}", file=sys.stderr)
        sys.exit(1)


def tenant_kind(tenant_id: str) -> str:
    return "personal" if tenant_id.startswith("per_") else "corporate"


def resolve_capability(
    req: dict,
    index: dict[str, list[dict]],
    tenant_id: str,
) -> tuple[dict | None, str | None]:
    cap_id = req["id"]
    req_mode = req["mode"]
    optional = req.get("optional", False)

    entries = index.get(cap_id)
    if not entries:
        return None, "CAPABILITY_NOT_FOUND"

    # Prefer current, then incubating (only if explicitly allowed), never deprecated
    current = [e for e in entries if e["state"] == "current"]
    incubating = [e for e in entries if e["state"] == "incubating"]
    deprecated = [e for e in entries if e["state"] == "deprecated"]

    if len(current) > 1:
        return None, "CAPABILITY_AMBIGUOUS"
    if current:
        chosen = current[0]
    elif incubating and req.get("allow_incubating", False):
        chosen = incubating[0]
    elif deprecated:
        return None, "DEPRECATED_ONLY"
    else:
        return None, "CAPABILITY_NOT_FOUND"

    if chosen["mode"] != req_mode:
        return None, "MODE_MISMATCH"

    if not chosen.get("grade"):
        return None, "UNGRADED"

    if tenant_kind(tenant_id) == "corporate" and not chosen["scope"]["tenant_isolated"]:
        return None, "TENANT_BOUNDARY_VIOLATION"

    return chosen, None


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--order", required=True)
    ap.add_argument("--registry", required=True)
    ap.add_argument("--schemas", default="schemas")
    ap.add_argument("--out", default=None)
    ap.add_argument("--strict", action="store_true", help="fail on any unresolved non-optional")
    args = ap.parse_args()

    schemas_dir = Path(args.schemas)
    order_schema = load_json(schemas_dir / "factory.order.v2.json")
    reg_schema = load_json(schemas_dir / "factory.registry.v1.json")
    res_schema = load_json(schemas_dir / "factory.resolution.v1.json")

    order = load_json(args.order)
    registry = load_json(args.registry)

    validate(Draft202012Validator(order_schema), order, "order")
    validate(Draft202012Validator(reg_schema), registry, "registry")

    if registry["seed_repo"] == "":
        print("registry has no seed — refusing to resolve", file=sys.stderr)
        return 1

    index: dict[str, list[dict]] = {}
    for cap in registry["capabilities"]:
        index.setdefault(cap["id"], []).append(cap)

    resolved, unresolved = [], []
    for req in order["capabilities"]:
        chosen, reason = resolve_capability(req, index, order["tenant_id"])
        if chosen is None:
            entry = {"id": req["id"], "reason": reason}
            if not req.get("optional", False):
                unresolved.append(entry)
            else:
                unresolved.append({**entry, "optional": True})
        else:
            resolved.append({
                "id": chosen["id"],
                "mode": chosen["mode"],
                "source_repo": chosen["source_repo"],
                "source_branch": chosen["source_branch"],
                "state": chosen["state"],
                "scope": chosen["scope"],
                "grade": chosen["grade"],
            })

    resolution = {
        "order_id": order["order_id"],
        "tenant_id": order["tenant_id"],
        "resolved_at": datetime.now(timezone.utc).isoformat(),
        "resolved": resolved,
        "unresolved": unresolved,
    }
    validate(Draft202012Validator(res_schema), resolution, "resolution")

    output = json.dumps(resolution, indent=2, sort_keys=True)
    if args.out:
        Path(args.out).write_text(output + "\n")
    print(output)

    if args.strict and any(not u.get("optional") for u in unresolved):
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

