## 7. `bin/idp-shed` — the shed recorder

```python
#!/usr/bin/env python3
"""
idp-shed — mark a capability or branch deprecated, and record the shed.
"""
from __future__ import annotations
import argparse, json, sys
from datetime import datetime, timezone
from pathlib import Path

try:
    import yaml
except ImportError:
    sys.exit("pip install pyyaml")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", required=True)
    ap.add_argument("--root", default=".")
    ap.add_argument("--capability", help="capability id to deprecate")
    ap.add_argument("--branch", help="branch name to deprecate")
    ap.add_argument("--superseded-by", default=None, help="repo:branch that won")
    ap.add_argument("--ledger", default="ledger/sheds.ndjson")
    args = ap.parse_args()

    path = Path(args.root) / args.repo / "capability.yaml"
    if not path.exists():
        print(f"no capability.yaml at {path}", file=sys.stderr)
        return 1

    data = yaml.safe_load(path.read_text())
    changed = False

    if args.branch:
        for b in data.get("branches", []):
            if b["name"] == args.branch and b["state"] != "deprecated":
                b["state"] = "deprecated"
                b["since"] = datetime.now(timezone.utc).date().isoformat()
                if args.superseded_by:
                    b.setdefault("supersedes", []).append(args.superseded_by)
                changed = True
        if not changed:
            print(f"branch {args.branch} not found or already deprecated", file=sys.stderr)
            return 1

    if args.capability:
        for c in data.get("capabilities", []):
            if c["id"] == args.capability and c["state"] != "deprecated":
                c["state"] = "deprecated"
                changed = True
        if not changed:
            print(f"capability {args.capability} not found or already deprecated", file=sys.stderr)
            return 1

    if not changed:
        print("nothing to shed", file=sys.stderr)
        return 1

    path.write_text(yaml.safe_dump(data, sort_keys=False))

    ledger = Path(args.ledger)
    ledger.parent.mkdir(parents=True, exist_ok=True)
    with ledger.open("a") as f:
        f.write(json.dumps({
            "event": "shed",
            "at": datetime.now(timezone.utc).isoformat(),
            "repo": args.repo,
            "capability": args.capability,
            "branch": args.branch,
            "superseded_by": args.superseded_by,
        }, sort_keys=True) + "\n")

    print(f"shed recorded: {path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

