## 8. `.github/workflows/registry.yml` — hourly collector

```yaml
name: capability-registry
on:
  schedule:
    - cron: "17 * * * *"
  workflow_dispatch:
  push:
    paths:
      - "capability.yaml"
      - "bin/idp-capability-collector"
      - "schemas/factory.contract.v1.json"

permissions:
  contents: write

jobs:
  collect:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0
          token: ${{ secrets.GITHUB_TOKEN }}

      - uses: actions/setup-python@v5
        with: { python-version: "3.12" }

      - run: pip install pyyaml jsonschema

      - name: Fetch sibling repos
        env:
          GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          mkdir -p sibling
          gh repo list chidionyema --limit 200 --json name -q '.[].name' | while read r; do
            gh repo clone "$r" "sibling/$r" -- --depth=1 || echo "skip $r"
          done

      - name: Run collector
        run: |
          python bin/idp-capability-collector \
            --root sibling \
            --out registry.json \
            --prev registry.json \
            --ledger ledger/sheds.ndjson

      - name: Validate output
        run: |
          python -c "
          import json, sys
          from jsonschema import Draft202012Validator
          reg = json.load(open('registry.json'))
          sch = json.load(open('schemas/factory.registry.v1.json'))
          Draft202012Validator(sch).validate(reg)
          print('registry valid')
          "

      - name: Commit
        run: |
          git config user.name "factory-bot"
          git config user.email "factory-bot@users.noreply.github.com"
          git add registry.json ledger/sheds.ndjson
          git diff --cached --quiet || git commit -m "chore(registry): hourly emit $(date -u +%Y-%m-%dT%H:%MZ)"
          git push
