## 5. `bin/idp-classify` — the classification pass

```python
#!/usr/bin/env python3
"""
idp-classify — classify every patch in the corpus as live | obsolete | superseded | unknown.
Pure function of (patch manifest, registry). No side effects except the output file.
"""
from __future__ import annotations
import argparse, json, sys
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

try:
    from jsonschema import Draft202012Validator
except ImportError:
    sys.exit("pip install jsonschema")


STATE_RANK = {"current": 0, "incubating": 1, "deprecated": 2}


def load_json(p: Path) -> dict:
    return json.loads(p.read_text())


def validate(validator: Draft202012Validator, data: dict, name: str) -> None:
    errors = sorted(validator.iter_errors(data), key=lambda e: e.path)
    if errors:
        for e in errors:
            print(f"{name}: {'.'.join(str(p) for p in e.absolute_path)}: {e.message}", file=sys.stderr)
        sys.exit(1)


def classify_one(patch: dict, registry: dict, index: dict) -> tuple[str, str, str | None]:
    """Return (classification, reason, superseded_by)."""
    target = patch["target"]
    repo = target["repo"]
    branch = target.get("branch")
    cap_id = target.get("capability")

    # 1. Target repo must exist in the registry (any branch).
    repo_branches = [b for b in registry["branches"] if b["repo"] == repo]
    if not repo_branches:
        return "obsolete", f"repo {repo} not present in registry", None

    # 2. If a capability is named, it must exist and be current/incubating.
    if cap_id:
        entries = index.get(cap_id, [])
        if not entries:
            return "obsolete", f"capability {cap_id} no longer exists", None
        if all(e["state"] == "deprecated" for e in entries):
            winner = next((e for e in entries if e["state"] != "deprecated"), None)
            if winner:
                return "superseded", f"{cap_id} superseded by {winner['source_repo']}", winner["source_repo"]
            return "obsolete", f"capability {cap_id} is deprecated with no successor", None

    # 3. If a branch is named, it must be current or incubating.
    if branch:
        match = next((b for b in repo_branches if b["branch"] == branch), None)
        if not match:
            return "obsolete", f"branch {repo}:{branch} no longer exists", None
        if match["state"] == "deprecated":
            return "obsolete", f"branch {repo}:{branch} is deprecated", None

    # 4. Superseded check: another patch, same target, later captured_at, same operation.
    #    (Caller passes patches grouped; here we accept an injected supersession map.)
    return "live", "target is current and no supersession detected", None


def find_supersessions(patches: list[dict]) -> dict[str, str]:
    """Map patch_id -> superseding patch_id where a later patch covers the same ground."""
    keyed: dict[tuple, list[dict]] = defaultdict(list)
    for p in patches:
        t = p["target"]
        key = (t["repo"], t.get("branch"), t.get("capability"), p["operation"])
        keyed[key].append(p)
    supersedes: dict[str, str] = {}
    for key, group in keyed.items():
        if len(group) < 2:
            continue
        group_sorted = sorted(group, key=lambda p: p["captured_at"])
        winner = group_sorted[-1]
        for p in group_sorted[:-1]:
            supersedes[p["patch_id"]] = winner["patch_id"]
    return supersedes


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--patches", required=True, help="directory of patch manifest JSON files")
    ap.add_argument("--registry", required=True)
    ap.add_argument("--schemas", default="schemas")
    ap.add_argument("--out", default="classification.json")
    ap.add_argument("--strict", action="store_true")
    args = ap.parse_args()

    patch_schema = load_json(Path(args.schemas) / "factory.patch.v1.json")
    class_schema = load_json(Path(args.schemas) / "factory.classification.v1.json")
    pv = Draft202012Validator(patch_schema)

    registry = load_json(Path(args.registry))
    index: dict[str, list[dict]] = defaultdict(list)
    for cap in registry["capabilities"]:
        index[cap["id"]].append(cap)

    patches: list[dict] = []
    for f in sorted(Path(args.patches).glob("*.json")):
        p = load_json(f)
        validate(pv, p, f.name)
        patches.append(p)

    if not patches:
        print("no patches found", file=sys.stderr)
        return 1

    supersedes = find_supersessions(patches)

    results = []
    for p in patches:
        if p["patch_id"] in supersedes:
            results.append({
                "patch_id": p["patch_id"],
                "classification": "superseded",
                "reason": f"superseded by {supersedes[p['patch_id']]}",
                "superseded_by": supersedes[p["patch_id"]],
            })
            continue
        cls, reason, sup = classify_one(p, registry, index)
        results.append({
            "patch_id": p["patch_id"],
            "classification": cls,
            "reason": reason,
            "superseded_by": sup,
        })

    summary = {"total": len(results), "live": 0, "obsolete": 0, "superseded": 0, "unknown": 0}
    for r in results:
        summary[r["classification"]] += 1

    out = {
        "schema": "factory.classification/v1",
        "classified_at": datetime.now(timezone.utc).isoformat(),
        "summary": summary,
        "patches": results,
    }
    validate(Draft202012Validator(class_schema), out, "classification")
    Path(args.out).write_text(json.dumps(out, indent=2, sort_keys=True) + "\n")

    print(f"classified {summary['total']} patches")
    print(f"  live={summary['live']}  obsolete={summary['obsolete']}  superseded={summary['superseded']}  unknown={summary['unknown']}")
    if args.strict and (summary["obsolete"] + summary["superseded"]) > 0:
        return 0  # classification is informational; strict does not fail on counts
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

