## 6. `bin/idp-rehydrate` — the rehydration branch

```python
#!/usr/bin/env python3
"""
idp-rehydrate — take one classified-live patch, resolve its requirements,
hydrate the payload from the corpus, apply it, grade it, and shed it if it fails.
"""
from __future__ import annotations
import argparse, hashlib, json, shutil, subprocess, sys, tempfile
from datetime import datetime, timezone
from pathlib import Path

try:
    from jsonschema import Draft202012Validator
except ImportError:
    sys.exit("pip install jsonschema")


def load_json(p: Path) -> dict:
    return json.loads(p.read_text())


def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return "sha256:" + h.hexdigest()


def hydrate_payload(corpus: Path, ref: str, dest: Path) -> None:
    """Locate the blob in the corpus by hash, copy it out."""
    target_hash = ref.split(":", 1)[1]
    # Corpus layout: corpus/objects/<aa>/<rest-of-hash>
    obj = corpus / "objects" / target_hash[:2] / target_hash[2:]
    if not obj.exists():
        # Fallback: linear scan (slow but correct; cached result by caller)
        for candidate in corpus.rglob(target_hash[2:]):
            if sha256_file(candidate) == ref:
                obj = candidate
                break
    if not obj.exists():
        raise FileNotFoundError(f"corpus blob not found for {ref}")
    dest.write_bytes(obj.read_bytes())


def resolve_requirements(requires: list[dict], registry: dict, tenant_id: str) -> tuple[list[dict], list[str]]:
    index: dict[str, list[dict]] = {}
    for cap in registry["capabilities"]:
        index.setdefault(cap["id"], []).append(cap)
    resolved, missing = [], []
    for req in requires:
        entries = index.get(req["id"], [])
        current = [e for e in entries if e["state"] == "current"]
        if not current:
            missing.append(req["id"])
            continue
        chosen = current[0]
        if chosen["mode"] != req["mode"]:
            missing.append(f"{req['id']}:mode-mismatch")
            continue
        if tenant_id.startswith("ten_") and not chosen["scope"]["tenant_isolated"]:
            missing.append(f"{req['id']}:tenant-boundary")
            continue
        resolved.append(chosen)
    return resolved, missing


def apply_patch(patch: dict, payload: Path, workdir: Path) -> tuple[bool, str]:
    """Apply by operation type. Returns (ok, detail)."""
    op = patch["operation"]
    repo_dir = workdir / patch["target"]["repo"]
    try:
        if op == "delete":
            target_file = repo_dir / payload.name
            if target_file.exists():
                target_file.unlink()
            return True, "deleted"
        if op in ("create", "modify", "refactor"):
            dest = repo_dir / payload.name
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(payload, dest)
            return True, f"{op}d {dest.relative_to(workdir)}"
        return False, f"unknown operation {op}"
    except Exception as e:
        return False, str(e)


def grade_patch(patch: dict, workdir: Path) -> tuple[bool, str]:
    gate = patch["grade"]["gate"]
    # Gate is a shell command run in the repo directory.
    repo_dir = workdir / patch["target"]["repo"]
    if not repo_dir.exists():
        return False, f"repo dir {repo_dir} missing"
    try:
        r = subprocess.run(
            gate, shell=True, cwd=repo_dir, capture_output=True, text=True, timeout=600,
        )
        if r.returncode == 0:
            return True, "gate passed"
        return False, f"gate failed rc={r.returncode}: {r.stderr.strip()[:400]}"
    except subprocess.TimeoutExpired:
        return False, "gate timed out"
    except Exception as e:
        return False, str(e)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--patch", required=True, help="patch manifest JSON")
    ap.add_argument("--corpus", required=True, help="path to 41MB corpus dir")
    ap.add_argument("--registry", required=True)
    ap.add_argument("--repos-root", required=True, help="parent dir containing repo checkouts")
    ap.add_argument("--schemas", default="schemas")
    ap.add_argument("--tenant-id", default="ten_factory_internal")
    ap.add_argument("--out", default=None)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--ledger", default="ledger/rehydrations.ndjson")
    args = ap.parse_args()

    patch = load_json(Path(args.patch))
    registry = load_json(Path(args.registry))
    res_schema = load_json(Path(args.schemas) / "factory.rehydration.v1.json")

    started = datetime.now(timezone.utc)
    steps: list[dict] = []

    # Resolve
    resolved, missing = resolve_requirements(patch["requires"], registry, args.tenant_id)
    if missing:
        steps.append({"step": "resolve", "result": "fail", "detail": f"missing: {missing}"})
        return _finish(args, patch, started, "aborted", steps, "resolve failed", res_schema)
    steps.append({"step": "resolve", "result": "ok", "detail": f"{len(resolved)} caps"})

    # Hydrate
    workdir = Path(tempfile.mkdtemp(prefix="rehydrate-"))
    try:
        payload = workdir / f"{patch['patch_id']}.blob"
        try:
            hydrate_payload(Path(args.corpus), patch["corpus_ref"], payload)
            if sha256_file(payload) != patch["corpus_ref"]:
                steps.append({"step": "hydrate", "result": "fail", "detail": "hash mismatch after hydrate"})
                return _finish(args, patch, started, "aborted", steps, "hydrate failed", res_schema)
            steps.append({"step": "hydrate", "result": "ok", "detail": f"{patch['size_bytes']} bytes"})
        except FileNotFoundError as e:
            steps.append({"step": "hydrate", "result": "fail", "detail": str(e)})
            return _finish(args, patch, started, "aborted", steps, "corpus miss", res_schema)

        # Stage a copy of the target repo into workdir
        src_repo = Path(args.repos_root) / patch["target"]["repo"]
        if not src_repo.exists():
            steps.append({"step": "apply", "result": "fail", "detail": f"repo {src_repo} not checked out"})
            return _finish(args, patch, started, "aborted", steps, "repo missing", res_schema)
        shutil.copytree(src_repo, workdir / patch["target"]["repo"], dirs_exist_ok=True)

        if args.dry_run:
            steps.append({"step": "apply", "result": "skip", "detail": "dry-run"})
            steps.append({"step": "grade", "result": "skip", "detail": "dry-run"})
            return _finish(args, patch, started, "aborted", steps, "dry-run", res_schema)

        # Apply
        ok, detail = apply_patch(patch, payload, workdir)
        steps.append({"step": "apply", "result": "ok" if ok else "fail", "detail": detail})
        if not ok:
            return _finish(args, patch, started, "shed", steps, "apply failed", res_schema)

        # Grade
        ok, detail = grade_patch(patch, workdir)
        steps.append({"step": "grade", "result": "ok" if ok else "fail", "detail": detail})
        if not ok:
            return _finish(args, patch, started, "shed", steps, "grade failed", res_schema)

        # Commit back
        try:
            shutil.copytree(workdir / patch["target"]["repo"], src_repo, dirs_exist_ok=True)
            steps.append({"step": "commit", "result": "ok", "detail": "copied back"})
        except Exception as e:
            steps.append({"step": "commit", "result": "fail", "detail": str(e)})
            return _finish(args, patch, started, "aborted", steps, "commit failed", res_schema)

        return _finish(args, patch, started, "applied", steps, "gate passed", res_schema)
    finally:
        shutil.rmtree(workdir, ignore_errors=True)


def _finish(args, patch, started, outcome, steps, reason, schema) -> int:
    finished = datetime.now(timezone.utc)
    out = {
        "schema": "factory.rehydration/v1",
        "patch_id": patch["patch_id"],
        "started_at": started.isoformat(),
        "finished_at": finished.isoformat(),
        "outcome": outcome,
        "reason": reason,
        "steps": steps,
    }
    Draft202012Validator(schema).validate(out)
    if args.out:
        Path(args.out).write_text(json.dumps(out, indent=2, sort_keys=True) + "\n")
    ledger = Path(args.ledger)
    ledger.parent.mkdir(parents=True, exist_ok=True)
    with ledger.open("a") as f:
        f.write(json.dumps(out, sort_keys=True) + "\n")
    print(json.dumps(out, indent=2, sort_keys=True))
    return 0 if outcome == "applied" else 1


if __name__ == "__main__":
    sys.exit(main())
```

