## 7. `bin/idp-execute` — the resolution→execution bridge

```python
#!/usr/bin/env python3
"""
idp-execute — consume an order + a resolution, build a DAG, hand off to agent-foundry,
meter the run, record the execution.
"""
from __future__ import annotations
import argparse, importlib, json, sys, time
from datetime import datetime, timezone
from pathlib import Path

try:
    from jsonschema import Draft202012Validator
except ImportError:
    sys.exit("pip install jsonschema")


def load_json(p: Path) -> dict:
    return json.loads(p.read_text())


def build_dag(order: dict, resolution: dict) -> dict:
    """A DAG node per resolved capability, chained in order."""
    nodes = []
    edges = []
    prev = None
    for i, r in enumerate(resolution["resolved"]):
        node_id = f"n{i}_{r['id']}"
        nodes.append({
            "id": node_id,
            "capability_id": r["id"],
            "mode": r["mode"],
            "source_repo": r["source_repo"],
            "source_branch": r["source_branch"],
            "scope": r["scope"],
        })
        if prev is not None:
            edges.append({"from": prev, "to": node_id})
        prev = node_id
    return {"nodes": nodes, "edges": edges}


def run_dag(dag: dict, order: dict, registry: dict, dry_run: bool) -> tuple[str, int]:
    """Hand the DAG to agent-foundry's army if available; otherwise dry-run."""
    try:
        af = importlib.import_module("af")
    except ImportError:
        af = None

    if dry_run or af is None:
        return ("ok" if not dry_run else "partial"), len(dag["nodes"])

    # agent-foundry expected interface: af.army(order=..., nodes=[...])
    try:
        af.army(order=order, nodes=dag["nodes"])
        return "ok", len(dag["nodes"])
    except Exception as e:
        print(f"agent-foundry run failed: {e}", file=sys.stderr)
        return "failed", len(dag["nodes"])


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--order", required=True)
    ap.add_argument("--resolution", required=True)
    ap.add_argument("--registry", required=True)
    ap.add_argument("--schemas", default="schemas")
    ap.add_argument("--out", default=None)
    ap.add_argument("--ledger", default="ledger/executions.ndjson")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    order = load_json(Path(args.order))
    resolution = load_json(Path(args.resolution))
    registry = load_json(Path(args.registry))
    ex_schema = load_json(Path(args.schemas) / "factory.execution.v1.json")

    if order["order_id"] != resolution["order_id"]:
        print("order_id mismatch", file=sys.stderr)
        return 1
    if order["tenant_id"] != resolution["tenant_id"]:
        print("tenant_id mismatch", file=sys.stderr)
        return 1
    if resolution["unresolved"] and any(not u.get("optional") for u in resolution["unresolved"]):
        print("resolution has non-optional unresolved capabilities", file=sys.stderr)
        return 1

    started = datetime.now(timezone.utc)
    t0 = time.monotonic()

    dag = build_dag(order, resolution)
    outcome, task_executions = run_dag(dag, order, registry, args.dry_run)
    wall_ms = int((time.monotonic() - t0) * 1000)

    out = {
        "schema": "factory.execution/v1",
        "order_id": order["order_id"],
        "tenant_id": order["tenant_id"],
        "started_at": started.isoformat(),
        "finished_at": datetime.now(timezone.utc).isoformat(),
        "outcome": outcome,
        "dag": dag,
        "meter": {"task_executions": task_executions, "wall_ms": wall_ms, "cost_usd": 0.0},
        "error": None,
    }
    Draft202012Validator(ex_schema).validate(out)
    if args.out:
        Path(args.out).write_text(json.dumps(out, indent=2, sort_keys=True) + "\n")
    ledger = Path(args.ledger)
    ledger.parent.mkdir(parents=True, exist_ok=True)
    with ledger.open("a") as f:
        f.write(json.dumps(out, sort_keys=True) + "\n")
    print(json.dumps(out, indent=2, sort_keys=True))
    return 0 if outcome == "ok" else 1


if __name__ == "__main__":
    sys.exit(main())
```

