## 9. `.github/workflows/rehydrate.yml` — the rehydration workflow

```yaml
name: rehydrate
on:
  workflow_dispatch:
    inputs:
      patch_id:
        description: "patch id to rehydrate (or 'live-batch' for all classified-live)"
        required: true
        default: "live-batch"
  schedule:
    - cron: "23 3 * * *"   # nightly batch

permissions:
  contents: write

jobs:
  classify:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with: { python-version: "3.12" }
      - run: pip install pyyaml jsonschema
      - name: Fetch registry
        run: git fetch origin registry && git checkout origin/registry -- registry.json
      - name: Classify
        run: |
          python bin/idp-classify \
            --patches corpus/patches \
            --registry registry.json \
            --schemas schemas \
            --out classification.json
      - uses: actions/upload-artifact@v4
        with:
          name: classification
          path: classification.json

  rehydrate:
    needs: classify
    runs-on: ubuntu-latest
    if: github.event.inputs.patch_id != 'live-batch' || github.event_name == 'schedule'
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with: { python-version: "3.12" }
      - run: pip install pyyaml jsonschema
      - uses: actions/download-artifact@v4
        with: { name: classification }
      - name: Rehydrate live patches
        run: |
          python - <<'PY'
          import json, subprocess, sys
          data = json.load(open("classification.json"))
          live = [p["patch_id"] for p in data["patches"] if p["classification"] == "live"]
          print(f"live patches: {len(live)}")
          for pid in live:
              r = subprocess.run([
                  sys.executable, "bin/idp-rehydrate",
                  "--patch", f"corpus/patches/{pid}.json",
                  "--corpus", "corpus",
                  "--registry", "registry.json",
                  "--repos-root", ".",
                  "--schemas", "schemas",
                  "--ledger", "ledger/rehydrations.ndjson",
              ])
              print(f"{pid}: rc={r.returncode}")
          PY
      - name: Commit ledger
        run: |
          git config user.name "factory-bot"
          git config user.email "factory-bot@users.noreply.github.com"
          git add ledger/rehydrations.ndjson
          git diff --cached --quiet || git commit -m "chore(rehydrate): batch $(date -u +%Y-%m-%dT%H:%MZ)"
          git push
