"""Shape lattice + subsumption. Total, decidable."""
import yaml
from pathlib import Path

_CACHE = {}

def _load():
    if "shapes" in _CACHE:
        return _CACHE["shapes"]
    p = Path(__file__).resolve().parent.parent / "schemas" / "shapes.yaml"
    if not p.exists():
        _CACHE["shapes"] = {"declared": set(), "atoms": set()}
        return _CACHE["shapes"]
    data = yaml.safe_load(p.read_text())["shape_system"]
    declared = {(d["sub"], d["sup"]) for d in data.get("declared_subsumptions", [])}
    atoms = {a["id"] for a in data.get("atoms", [])}
    _CACHE["shapes"] = {"declared": declared, "atoms": atoms}
    return _CACHE["shapes"]

def parse(s):
    s = s.strip()
    if s.endswith("?"):
        return ("optional", parse(s[:-1]))
    if s.startswith("[") and s.endswith("]"):
        return ("list", parse(s[1:-1]))
    if "|" in s:
        return ("union", tuple(parse(p) for p in s.split("|")))
    if s.startswith("{") and s.endswith("}"):
        inner = s[1:-1].strip()
        fields = {}
        depth = 0
        buf = ""
        parts = []
        for ch in inner:
            if ch in "{[": depth += 1
            elif ch in "}]": depth -= 1
            if ch == "," and depth == 0:
                parts.append(buf); buf = ""
            else:
                buf += ch
        if buf.strip(): parts.append(buf)
        for p in parts:
            if ":" not in p: continue
            k, v = p.split(":", 1)
            fields[k.strip()] = parse(v.strip())
        return ("record", fields)
    return ("atom", s)

def to_str(node):
    k, v = node
    if k == "atom": return v
    if k == "optional": return to_str(v) + "?"
    if k == "list": return "[" + to_str(v) + "]"
    if k == "union": return "|".join(to_str(m) for m in v)
    if k == "record": return "{" + ", ".join(f"{k2}: {to_str(t)}" for k2, t in v.items()) + "}"
    return "any"

def subsumes(sup: str, sub: str, _depth=0) -> bool:
    if _depth > 32: return False
    if sup == "any" or sup == sub: return True
    cfg = _load()
    if (sub, sup) in cfg["declared"] or (sup, sub) in cfg["declared"]:
