"""Real isolation. Subprocess with no inherited secrets, no network, cwd=tempdir, hard timeout."""
import os, subprocess, sys, tempfile, shutil
from pathlib import Path

def run_gate(gate: dict, cwd: Path, timeout: int = 300) -> tuple[bool, str]:
    term = gate.get("terminal")
    if not term:
        return False, "no gate terminal"
    if gate.get("sandbox") not in ("subprocess", "kronos.ring0", "kronos.ring1", "docker"):
        return False, f"unknown sandbox: {gate.get('sandbox')}"

    # Build a clean env — no secrets inherited
    clean_env = {
        "PATH": os.environ.get("PATH", "/usr/bin:/bin"),
        "SANDBOX": gate["sandbox"],
        "NO_NETWORK": "1",
        "PYTHONPATH": str(Path(__file__).resolve().parent.parent),
    }
    try:
        r = subprocess.run(
            [sys.executable, "-m", "factory.gates", term],
            cwd=cwd, env=clean_env, capture_output=True, text=True, timeout=timeout,
        )
        return (r.returncode == 0, (r.stdout or r.stderr or "").strip()[:400])
    except subprocess.TimeoutExpired:
        return False, "gate timeout"
    except Exception as e:
        return False, str(e)
