#!/usr/bin/env python3
"""Run this to accept webhooks from every HTTP-webhook surface. Runs on :8000."""
import json, os, sys, hmac, hashlib
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
from datetime import datetime, timezone
from factory import ledger
from factory.surfaces.registry import all_surfaces

INBOX = Path("queue/webhook_inbox"); INBOX.mkdir(parents=True, exist_ok=True)

ROUTES = {
    "/webhook/notion":  "notion",
    "/webhook/linear":  "linear",
    "/webhook/stripe":  "stripe",
    "/webhook/github":  "github",
    "/webhook/telegram": "telegram",
    "/webhook/whatsapp": "whatsapp",
    "/webhook/slack":   "slack",
    "/webhook/voice":   "voice",
}

class Handler(BaseHTTPRequestHandler):
    def do_POST(self):
        surface_id = ROUTES.get(self.path)
        if not surface_id:
            self.send_response(404); self.end_headers(); return
        length = int(self.headers.get("Content-Length", "0"))
        raw = self.rfile.read(length) if length else b""
        try:
            payload = json.loads(raw) if raw else {}
        except Exception:
            payload = {"raw": raw.decode(errors="ignore")}

        # Telegram-specific routing: write to telegram_receipts if callback_query
        if surface_id == "telegram" and payload.get("callback_query"):
            path = Path("queue/telegram_receipts"); path.mkdir(parents=True, exist_ok=True)
            (path / f"{datetime.now(timezone.utc).timestamp()}.json").write_text(json.dumps(payload))
        elif surface_id == "whatsapp":
            path = Path("queue/whatsapp_in"); path.mkdir(parents=True, exist_ok=True)
            (path / f"{datetime.now(timezone.utc).timestamp()}.json").write_text(json.dumps(payload))
        elif surface_id == "voice":
            path = Path("queue/voice_in"); path.mkdir(parents=True, exist_ok=True)
            (path / f"{datetime.now(timezone.utc).timestamp()}.json").write_text(json.dumps(payload))
        elif surface_id == "slack":
            path = Path("queue/slack_in"); path.mkdir(parents=True, exist_ok=True)
            (path / f"{datetime.now(timezone.utc).timestamp()}.json").write_text(json.dumps(payload))
        else:
            (INBOX / f"{surface_id}_{datetime.now(timezone.utc).timestamp():.6f}.json").write_text(
                json.dumps({"surface": surface_id, "payload": payload}))

        ledger.write("webhooks", {"path": self.path, "surface": surface_id, "size": len(raw)})
        self.send_response(200); self.send_header("Content-Type", "application/json"); self.end_headers()
        self.wfile.write(b'{"ok":true}')

    def log_message(self, *args): pass

if __name__ == "__main__":
    port = int(os.environ.get("WEBHOOK_PORT", "8000"))
    print(f"webhook server on :{port}  routes: {list(ROUTES.keys())}")
    HTTPServer(("0.0.0.0", port), Handler).serve_forever()
