1. factory/generate_capabilities.py — the registry generator
Walks every repo. Detects what it produces. Emits capability.yaml. Idempotent, honest (writes state: incubating when it can't prove current).

python
#!/usr/bin/env python3
"""
Walk every repo under ROOT, detect capabilities, emit capability.yaml.
Heuristics are explicit; every emitted terminal carries source & confidence.
Never overwrites an existing capability.yaml without --force.
"""
import argparse, json, os, re, sys, hashlib
from pathlib import Path
from datetime import date

try:
    import yaml
except ImportError:
    import subprocess; subprocess.run([sys.executable, "-m", "pip", "install", "-q", "pyyaml"], check=True)
    import yaml

TODAY = date.today().isoformat()
DEFAULT_GATE = {"terminal": "delivery_delivered", "sandbox": "subprocess"}
DEFAULT_GRADE = lambda metric="accuracy", polarity="maximize": {
    "metric": metric, "polarity": polarity, "scale": [0, 1], "gate": DEFAULT_GATE,
}

def emit_terminal(tid, name, in_shape, out_shape, *, mode="function", cls="act",
                  resources=None, tenant_isolated=True, role="branch",
                  state="incubating", grade=None, produces_again=False):
    return {"terminal": {
        "id": tid, "name": name,
        "input":  {"shape": in_shape},
        "output": {"shape": out_shape},
        "grade": grade or DEFAULT_GRADE(),
        "state": state, "since": TODAY, "supersedes": [],
        "produces_again": produces_again,
        "annotations": {
            "class": cls, "mode": mode,
            "scope": {"resources": resources or ["filesystem"],
                      "secrets": {}, "tenant_isolated": tenant_isolated},
            "role": role,
        },
    }}

# ---------- detectors ----------

def detect_python_tools(repo: Path) -> list[dict]:
    """A repo's tools/*.py or */tools/*.py are capability candidates."""
    out = []
    for tools_dir in list(repo.glob("tools")) + list(repo.glob("*/tools")):
        for f in sorted(tools_dir.glob("*.py")):
            if f.name.startswith("_"): continue
            stem = f.stem
            if not re.match(r"^[a-z][a-z0-9_]*$", stem): continue
            cap_id = stem.replace("_", "-").rstrip("-tool").rstrip("-")
            if not cap_id: continue
            out.append({
                "id": cap_id, "name": stem.replace("_", " ").title(),
                "in": {"shape": "any"}, "out": {"shape": "any"},
                "mode": "function", "cls": "act", "resources": ["filesystem"],
                "role": "branch", "state": "incubating",
                "source": str(f.relative_to(repo)),
            })
    return out

def detect_skills(repo: Path) -> list[dict]:
    out = []
    for skills_dir in list(repo.glob("skills")) + list(repo.glob("*/skills")):
        for d in sorted(skills_dir.iterdir()):
            if not d.is_dir(): continue
            sid = d.name.lower().replace("_", "-").replace(" ", "-")
            if not re.match(r"^[a-z][a-z0-9-]*$", sid): continue
            out.append({
                "id": f"skill.{sid}", "name": d.name.replace("-", " ").title(),
                "in": {"shape": "any"}, "out": {"shape": "any"},
                "mode": "function", "cls": "act", "resources": ["filesystem"],
                "role": "branch", "state": "incubating",
                "source": str(d.relative_to(repo)),
            })
    return out

def detect_mcp_plugins(repo: Path) -> list[dict]:
    out = []
    for plugins_dir in [repo / "mcp" / "plugins", repo / "plugins"]:
        if not plugins_dir.exists(): continue
        for f in sorted(plugins_dir.glob("*.py")):
            if f.name.startswith("_"): continue
            pid = f.stem.replace("_", "-")
            out.append({
                "id": f"mcp.{pid}", "name": f.stem.replace("_", " ").title(),
                "in": {"shape": "any"}, "out": {"shape": "any"},
                "mode": "function", "cls": "act", "resources": ["filesystem"],
                "role": "branch", "state": "incubating",
                "source": str(f.relative_to(repo)),
            })
    return out

def detect_rust_crates(repo: Path) -> list[dict]:
    out = []
    for cargo in [repo / "Cargo.toml", *repo.glob("*/Cargo.toml")]:
        if not cargo.exists(): continue
        try:
            data = yaml.safe_load(cargo.read_text()) or {}
        except Exception:
            continue
        name = (data.get("package") or {}).get("name") or cargo.parent.name
        out.append({
            "id": f"crate.{name.replace('_','-')}", "name": name,
            "in": {"shape": "any"}, "out": {"shape": "any"},
            "mode": "function", "cls": "compute", "resources": ["compute"],
            "role": "branch", "state": "incubating",
            "source": str(cargo.relative_to(repo)),
        })
    return out

def detect_bin_scripts(repo: Path) -> list[dict]:
    """idp/bin/* — treat the important ones as callable terminals."""
    out = []
    bin_dir = repo / "bin"
    if not bin_dir.exists(): return out
    for f in sorted(bin_dir.iterdir()):
        if f.name.startswith("_") or f.name.startswith("."): continue
        if not f.is_file(): continue
        if not (f.name.endswith(".py") or os.access(f, os.X_OK)): continue
        stem = f.stem if f.suffix == ".py" else f.name
        if not re.match(r"^[a-z][a-z0-9-]*$", stem): continue
        out.append({
            "id": stem, "name": stem.replace("-", " ").title(),
            "in": {"shape": "{args: json}"}, "out": {"shape": "json"},
            "mode": "function", "cls": "act", "resources": ["filesystem"],
            "role": "rail", "state": "incubating",
            "source": str(f.relative_to(repo)),
        })
    return out

def detect_http_routes(repo: Path) -> list[dict]:
    """Look for FastAPI/Flask route decorators → surface terminals."""
    out = []
    route_re = re.compile(r'@(app|router)\.(get|post|put|delete)\(\s*["\']([^"\']+)')
    for py in repo.rglob("*.py"):
        if any(p in py.parts for p in ("node_modules", ".venv", "venv", "__pycache__")):
            continue
        try:
            text = py.read_text(errors="ignore")
        except Exception:
            continue
        for m in route_re.finditer(text):
            method, path = m.group(2).upper(), m.group(3)
            if path in ("/health", "/", "/metrics"): continue
            sid = f"{method.lower()}.{repo.name}.{path.strip('/').replace('/', '-').replace('{','').replace('}','')}"
            sid = re.sub(r"[^a-z0-9.\-]", "", sid.lower())
            if len(sid) > 62: continue
            out.append({
                "id": sid, "name": f"{method} {path}",
                "in": {"shape": "{body: json}"}, "out": {"shape": "json"},
                "mode": "function", "cls": "surface", "resources": [repo.name],
                "role": "branch", "state": "incubating",
                "source": str(py.relative_to(repo)),
            })
    return out

DETECTORS = [
    detect_python_tools,
    detect_skills,
    detect_mcp_plugins,
    detect_rust_crates,
    detect_bin_scripts,
    detect_http_routes,
]

def detect_repo_role(repo: Path) -> str:
    name = repo.name
    if name in ("idp", "estate-core", "estate-guards", "estate-secrets", "crew"):
        return "rail"
    if name in ("agent-foundry",):
        return "seed-expression"
    if name.endswith("-platform") or "commerce" in name or "medusa" in name:
        return "product"
    return "branch"

def build_declaration(repo: Path) -> dict:
    terminals = []
    for det in DETECTORS:
        try:
            for t in det(repo):
                terminals.append(t)
        except Exception as e:
            print(f"  [{repo.name}] detector {det.__name__} failed: {e}", file=sys.stderr)
    # dedupe by id, prefer earlier state
    seen = {}
    for t in terminals:
        if t["id"] not in seen:
            seen[t["id"]] = t
    terminals = list(seen.values())
    role = detect_repo_role(repo)
    for t in terminals:
        t["role"] = role
        t.setdefault("state", "incubating")
    return {"terminals": [emit_terminal(
        t["id"], t["name"], t["in"]["shape"], t["out"]["shape"],
        mode=t["mode"], cls=t["cls"], resources=t["resources"],
        role=t["role"], state=t["state"],
    )["terminal"] for t in terminals]}

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=str(Path.home() / "Documents" / "code"))
    ap.add_argument("--out-dir", default=None, help="where to write; default: each repo's root")
    ap.add_argument("--force", action="store_true", help="overwrite existing capability.yaml")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    root = Path(args.root).resolve()
    stats = {"repos": 0, "generated": 0, "skipped": 0, "terminals": 0, "empty": 0}
    for repo in sorted(root.iterdir()):
        if not repo.is_dir() or repo.name.startswith("."):
            continue
        stats["repos"] += 1
        target = (Path(args.out_dir) / repo.name / "capability.yaml") if args.out_dir \
                 else (repo / "capability.yaml")
        if target.exists() and not args.force:
            stats["skipped"] += 1
            continue
        decl = build_declaration(repo)
        if not decl["terminals"]:
            stats["empty"] += 1
            print(f"[{repo.name}] no terminals detected — skipped")
            continue
        text = yaml.safe_dump(decl, sort_keys=False)
        if args.dry_run:
            print(f"--- {target} ---\n{text}")
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text)
            print(f"[{repo.name}] {len(decl['terminals'])} terminals → {target.relative_to(root)}")
        stats["generated"] += 1
        stats["terminals"] += len(decl["terminals"])

    print(f"\n{stats['repos']} repos, {stats['generated']} generated, "
          f"{stats['skipped']} skipped, {stats['empty']} empty, "
          f"{stats['terminals']} terminals total")

if __name__ == "__main__":
    main()
2. factory/secrets.py — real vault vend
Multiple backends. Refuses to fall back to env unless ALLOW_ENV_SECRETS=1.

python
import os, json, subprocess, urllib.request, urllib.parse, base64, re
from pathlib import Path

class SecretError(Exception): pass
class SecretUnavailable(SecretError): pass

_CACHE: dict[str, tuple[str, float]] = {}
CACHE_TTL = 300  # 5 minutes

def vend(ref: str, tenant: str = "factory") -> str:
    """Resolve a secret reference. Every backend must produce a real value or raise."""
    if not isinstance(ref, str):
        raise SecretError(f"secret ref must be a string, got {type(ref).__name__}")
    if not ref:
        raise SecretError("empty secret ref")

    # cache
    import time
    if ref in _CACHE:
        val, exp = _CACHE[ref]
        if time.time() < exp:
            return val
    val = _resolve(ref, tenant)
    _CACHE[ref] = (val, time.time() + CACHE_TTL)
    return val

def _resolve(ref: str, tenant: str) -> str:
    scheme, _, path = ref.partition("://")
    if not scheme:
        raise SecretError(f"ref must include scheme://: {ref}")
    fn = {
        "vault":     _hashicorp_vault,
        "sops":      _sops_file,
        "op":        _onepassword,
        "env":       _env,
        "file":      _file,
        "jit":       _jit_broker,
    }.get(scheme)
    if fn is None:
        raise SecretError(f"unsupported secret scheme: {scheme}")

    # env only allowed when explicitly permitted
    if scheme == "env" and os.environ.get("ALLOW_ENV_SECRETS") != "1":
        raise SecretUnavailable("env scheme disabled; set ALLOW_ENV_SECRETS=1 to allow")

    return fn(ref, path, tenant)

# ----- backends -----

def _hashicorp_vault(ref: str, path: str, tenant: str) -> str:
    """vault://secret/data/foo#key — HashiCorp Vault HTTP API."""
    addr = os.environ.get("VAULT_ADDR")
    token = os.environ.get("VAULT_TOKEN")
    if not (addr and token):
        raise SecretUnavailable("VAULT_ADDR / VAULT_TOKEN not set")
    key = None
    if "#" in path:
        path, key = path.split("#", 1)
    url = addr.rstrip("/") + "/v1/" + path.lstrip("/")
    req = urllib.request.Request(url, headers={"X-Vault-Token": token})
    with urllib.request.urlopen(req, timeout=10) as r:
        data = json.loads(r.read())
    node = data.get("data", {})
    if "data" in node: node = node["data"]  # kv2
    if key:
        if key not in node:
            raise SecretError(f"key {key} not in {path}")
        return str(node[key])
    return json.dumps(node)

def _sops_file(ref: str, path: str, tenant: str) -> str:
    """sops:///abs/path/file.enc.yaml#KEY — decrypt via sops CLI."""
    key = None
    if "#" in path:
        path, key = path.split("#", 1)
    # support `~` expansion
    p = Path(path).expanduser()
    if not p.exists():
        raise SecretUnavailable(f"sops file not found: {p}")
    try:
        r = subprocess.run(["sops", "-d", "--output-type", "yaml", str(p)],
                           capture_output=True, text=True, timeout=30)
    except FileNotFoundError:
        raise SecretUnavailable("sops CLI not installed")
    if r.returncode != 0:
        raise SecretError(f"sops failed: {r.stderr.strip()[:200]}")
    import yaml
    data = yaml.safe_load(r.stdout)
    if not key:
        return json.dumps(data)
    parts = key.split(".")
    node = data
    for part in parts:
        if not isinstance(node, dict) or part not in node:
            raise SecretError(f"key path {key} not in {p}")
        node = node[part]
    return str(node)

def _onepassword(ref: str, path: str, tenant: str) -> str:
    """op://Vault/Item/Field — 1Password CLI."""
    try:
        r = subprocess.run(["op", "read", f"op://{path}"],
                           capture_output=True, text=True, timeout=15)
    except FileNotFoundError:
        raise SecretUnavailable("1Password CLI (op) not installed")
    if r.returncode != 0:
        raise SecretError(f"op read failed: {r.stderr.strip()[:200]}")
    return r.stdout.strip()

def _env(ref: str, path: str, tenant: str) -> str:
    if path not in os.environ:
        raise SecretUnavailable(f"env var not set: {path}")
    return os.environ[path]

def _file(ref: str, path: str, tenant: str) -> str:
    p = Path(path).expanduser()
    if not p.exists():
        raise SecretUnavailable(f"file not found: {p}")
    mode = p.stat().st_mode & 0o777
    if mode & 0o077:
        import sys
        print(f"WARNING: secret file {p} has loose perms ({oct(mode)})", file=sys.stderr)
    return p.read_text().strip()

def _jit_broker(ref: str, path: str, tenant: str) -> str:
    """jit://<service>/<key> — delegates to the estate's jit-broker HTTP service."""
    broker = os.environ.get("JIT_BROKER_URL")
    if not broker:
        raise SecretUnavailable("JIT_BROKER_URL not set")
    body = json.dumps({"ref": ref, "tenant": tenant}).encode()
    req = urllib.request.Request(broker.rstrip("/") + "/vend", method="POST", data=body,
                                 headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=10) as r:
        data = json.loads(r.read())
    if "token" not in data:
        raise SecretError(f"jit-broker response missing token: {data}")
    return data["token"]

# ----- scanner: refuse literal secrets at admission -----

SECRET_PATTERNS = [
    re.compile(rb"Bearer\s+[A-Za-z0-9\-_\.=]{20,}"),
    re.compile(rb"sk-[A-Za-z0-9]{20,}"),
    re.compile(rb"ghp_[A-Za-z0-9]{36,}"),
    re.compile(rb"xoxb-[A-Za-z0-9-]{20,}"),
    re.compile(rb"-----BEGIN [A-Z ]+PRIVATE KEY-----"),
    re.compile(rb"AKIA[0-9A-Z]{16}"),
]

def refuse_literal_secrets(raw: bytes, source: str) -> None:
    for pat in SECRET_PATTERNS:
        m = pat.search(raw)
        if m:
            raise SecretError(f"literal secret detected in {source}: {pat.pattern!r}")
