# factory/sandbox.py — patched to never pass secrets to subprocess
import os, subprocess, sys
from pathlib import Path
from . import secrets as S

def run_gate(gate: dict, cwd: Path, allowed_secrets: list[str] | None = None) -> tuple[bool, str]:
    term = gate.get("terminal")
    if not term: return False, "NO_GATE_TERMINAL"
    sandbox = gate.get("sandbox") or "subprocess"
    if sandbox not in ("subprocess", "kronos.ring0", "kronos.ring1", "docker"):
        return False, f"UNKNOWN_SANDBOX_{sandbox}"

    # Only pass explicitly-allowed secrets; and only as inline env vars, never inherited
    env = {"PATH": "/usr/bin:/bin", "NO_NETWORK": "1", "PYTHONPATH": str(Path(__file__).resolve().parent.parent)}
    for name in (allowed_secrets or []):
        try:
            env[name] = S.vend(f"vault://factory/gates/{term}/{name}", tenant="factory")
        except Exception:
            pass  # don't fail the gate on missing optional secrets
    try:
        r = subprocess.run([sys.executable, "-m", "factory.gates", term],
                           cwd=cwd, env=env, capture_output=True, text=True, timeout=300)
        return r.returncode == 0, (r.stdout or r.stderr or "").strip()[:400]
    except subprocess.TimeoutExpired:
        return False, "GATE_TIMEOUT"
    except FileNotFoundError:
        return False, f"SANDBOX_UNAVAILABLE_{sandbox}"
    except Exception as e:
        return False, f"{type(e).__name__}: {e}"
