      id: army
      name: "Army"
      input:  { shape: "{goal: text}" }
      output: { shape: "{ran: text}" }
      grade:
        metric: accuracy
        polarity: maximize
        scale: [0,1]
        gate: { terminal: grammar.admission_test, sandbox: subprocess }
      state: current
      since: "2026-09-24"
