def test_idempotent_execution(tmp_path, monkeypatch):
    """Same order + resolution + bucket → same execution_id, one execution."""
    fresh_env(tmp_path, monkeypatch)
    import importlib, factory.exec
    importlib.reload(factory.exec)
    # craft a fake run_dag that increments a counter (proves it's called once)
