#!/usr/bin/env python3
"""Exchange AppRole creds for a Vault token, export for the factory process."""
import json, os, sys, urllib.request

def main():
    addr = os.environ["VAULT_ADDR"].rstrip("/")
    role = os.environ["VAULT_ROLE_ID"]
    sid  = os.environ["VAULT_SECRET_ID"]
    body = json.dumps({"role_id": role, "secret_id": sid}).encode()
    req = urllib.request.Request(f"{addr}/v1/auth/approle/login", method="POST",
                                 data=body, headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=10) as r:
        data = json.loads(r.read())
    token = data["auth"]["client_token"]
    ttl   = data["auth"]["lease_duration"]
    print(f"VAULT_TOKEN={token}")
    print(f"VAULT_TOKEN_TTL={ttl}", file=sys.stderr)

if __name__ == "__main__":
    main()
