#!/usr/bin/env bash
# Runs after deploy. Every check must pass or the deploy is rolled back.
set -euo pipefail

BASE="${FACTORY_BASE:-http://localhost:8080}"
FAIL=0

check() {
  local name="$1" cmd="$2"
  if eval "$cmd" > /dev/null 2>&1; then
    echo "  ✓ $name"
  else
    echo "  ✗ $name"
    FAIL=$((FAIL+1))
  fi
}

echo "== smoke =="
