#!/usr/bin/env python3
"""
pobr-mcp — the only tool the agent has.

Exposes exactly one MCP tool: pobr_submit(receipt).
If the receipt passes the gate, returns a signed grant token.
If it fails, returns a structured rejection. No grant, no human access.

The gate is deterministic. No LLM. No reasoning. Just assertions.
"""
from __future__ import annotations

import json
import os
import sys
import time
import uuid
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
pobr_gate = __import__("pobr_gate")
pobr_schema = __import__("pobr_schema")

GateResult = pobr_gate.GateResult
Admission = pobr_gate.Admission
gate = pobr_gate.gate
receipt_from_dict = pobr_gate.receipt_from_dict

GRANT_DIR = Path.home() / ".estate" / "grants"
GRANT_DIR.mkdir(parents=True, exist_ok=True)

# Public key for the agent's identity. Agent must sign its own receipts.
PUBKEY_PATH = Path.home() / ".estate" / "keys" / "agent.pub.pem"
ANCHOR_DIR = Path.home() / ".estate" / "anchors"


def _send(obj):
    sys.stdout.write(json.dumps(obj) + "\n")
    sys.stdout.flush()


def _handle(req: dict) -> dict:
    method = req.get("method")
    params = req.get("params", {}) or {}

    if method == "initialize":
        return {
            "protocolVersion": "2024-11-05",
            "capabilities": {"tools": {}},
            "serverInfo": {"name": "pobr-gate", "version": "1.0"},
        }

    if method == "tools/list":
        return {"tools": [
            {
                "name": "pobr_submit",
                "description": (
                    "Submit a Proof-of-Bayesian-Reasoning receipt. "
                    "This is the ONLY way to reach the human. "
                    "The receipt must include: data points consulted and excluded "
                    "with reasons, hypotheses with priors and justifications, "
                    "likelihoods, computed posterior, calibration metrics (ECE, Brier), "
                    "prior sensitivity sweep, faithfulness check across ≥3 inference "
                    "passes, and a counterfactual commitment naming a verifier. "
                    "If it fails any check, you get a structured rejection with "
                    "remediation and no grant. You may not reason around this."
                ),
                "inputSchema": {
                    "type": "object",
                    "properties": {"receipt": {"type": "object"}},
                    "required": ["receipt"],
                },
            }
        ]}

    if method == "tools/call":
        tool = params.get("name")
        if tool != "pobr_submit":
            return {"content": [{"type": "text", "text": f"REFUSED: unknown tool {tool}"}]}

        try:
            receipt = receipt_from_dict(params["arguments"]["receipt"])
        except Exception as e:
            return {"content": [{"type": "text", "text": f"REFUSED: receipt malformed: {e}"}]}

        pubkey = PUBKEY_PATH.read_bytes()
        result = gate(receipt, pubkey, ANCHOR_DIR)

        if result.decision == Admission.GRANTED:
            grant_id = f"grant-{uuid.uuid4().hex[:12]}"
            (GRANT_DIR / f"{grant_id}.json").write_text(json.dumps({
                "grant_id": grant_id,
                "receipt_root": receipt.merkle_root,
                "agent_id": receipt.agent_id,
                "issued_at": time.time(),
                "expires_at": time.time() + 300,  # 5 min
            }, indent=2))
            return {"content": [{"type": "text", "text": json.dumps({
                "decision": "ADMITTED",
                "grant_id": grant_id,
                "expires_in_seconds": 300,
                "receipt_root": receipt.merkle_root,
                "note": "You may now emit exactly one message to the human. "
                        "Include grant_id in the message. No further tool calls.",
            }, indent=2)}]}

        return {"content": [{"type": "text", "text": json.dumps({
            "decision": "REJECTED",
            "reason": result.reason,
            "detail": result.detail,
            "remediation": result.remediation,
            "receipt_root": result.receipt_root,
        }, indent=2)}]}

    return {}


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
        except Exception:
            continue
        if "id" not in req:
            continue
        _send({"jsonrpc": "2.0", "id": req["id"], "result": _handle(req)})


if __name__ == "__main__":
    main()

