// cmd/bootstrap/main.go
package main

import (
    "context"
    "crypto/ed25519"
    "crypto/rand"
    "crypto/x509"
    "encoding/base64"
    "encoding/json"
    "encoding/pem"
    "fmt"
    "io"
    "net/http"
    "net/url"
    "os"
    "path/filepath"
    "strings"
    "time"

    "github.com/oracle/oci-go-sdk/v65/common"
    "github.com/oracle/oci-go-sdk/v65/secrets"
    "github.com/oracle/oci-go-sdk/v65/vault"
    "github.com/spiffe/go-spiffe/v2/spiffeid"
    "github.com/spiffe/go-spiffe/v2/workloadapi"
)

type TokenExchangeResponse struct {
    AccessToken string `json:"access_token"`
    TokenType   string `json:"token_type"`
    ExpiresIn   int    `json:"expires_in"`
}

type WorkloadTokenProvider struct {
    token string
}

func (w WorkloadTokenProvider) SecurityToken() (string, error) {
    return w.token, nil
}

func main() {
    ctx, cancel := context.WithTimeout(context.Background(), 45*time.Second)
    defer cancel()

    spireSocketPath := os.Getenv("SPIRE_AGENT_SOCKET")
    if spireSocketPath == "" {
        spireSocketPath = "unix:///run/spire/sockets/agent.sock"
    }

    ociTokenURL := os.Getenv("OCI_IAM_TOKEN_ENDPOINT") // e.g., https://identity..oci.oraclecloud.com/oauth2/v1/token
    ociScope := os.Getenv("OCI_IAM_SCOPE")             // urn:oracle:identity:domain:root
    vaultOCID := os.Getenv("OCI_VAULT_OCID")
    compartmentOCID := os.Getenv("OCI_COMPARTMENT_OCID")
    agentURN := os.Getenv("AGENT_URN") // e.g., urn:aid:oke:research-agent
    outputKeyPath := "/run/secrets/agent-identity/ed25519.key"

    if ociTokenURL == "" || vaultOCID == "" || agentURN == "" {
        fmt.Fprintf(os.Stderr, "FATAL: OCI_IAM_TOKEN_ENDPOINT, OCI_VAULT_OCID, and AGENT_URN must be defined\n")
        os.Exit(1)
    }

    // 1. Acquire JWT-SVID from SPIRE Workload API
    client, err := workloadapi.New(ctx, workloadapi.WithAddress(spireSocketPath))
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Failed to connect to SPIRE workload API: %v\n", err)
        os.Exit(1)
    }
    defer client.Close()

    audience := ociTokenURL
    jwtSource, err := workloadapi.NewJWTSource(ctx, workloadapi.WithClient(client))
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Failed to create JWT source: %v\n", err)
        os.Exit(1)
    }
    defer jwtSource.Close()

    svid, err := jwtSource.FetchJWTSVID(ctx, workloadapi.TargetAudience(audience))
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Failed to fetch JWT-SVID from SPIRE: %v\n", err)
        os.Exit(1)
    }

    // 2. Perform RFC 8693 Token Exchange against OCI IAM
    data := url.Values{}
    data.Set("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange")
    data.Set("subject_token", svid.Marshal())
    data.Set("subject_token_type", "urn:ietf:params:oauth:token-type:jwt")
    data.Set("requested_token_type", "urn:ietf:params:oauth:token-type:access_token")
    data.Set("scope", ociScope)

    req, err := http.NewRequestWithContext(ctx, "POST", ociTokenURL, strings.NewReader(data.Encode()))
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Failed to build token exchange request: %v\n", err)
        os.Exit(1)
    }
    req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

    resp, err := http.DefaultClient.Do(req)
    if err != nil || resp.StatusCode != http.StatusOK {
        body, _ := io.ReadAll(resp.Body)
        fmt.Fprintf(os.Stderr, "FATAL: OCI IAM token exchange rejected (Status: %d, Response: %s): %v\n", resp.StatusCode, string(body), err)
        os.Exit(1)
    }

    var tokenResp TokenExchangeResponse
    if err := json.NewDecoder(resp.Body).Decode(&tokenResp); err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Unable to parse OCI IAM response: %v\n", err)
        os.Exit(1)
    }
    resp.Body.Close()

    // 3. Authenticate to OCI Vault using Federated Workload Token
    authProvider := common.NewCustomSecurityTokenProvider(tokenResp.AccessToken)
    vaultClient, err := vault.NewVaultsClientWithConfigurationProvider(authProvider)
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Initializing OCI Vault Client: %v\n", err)
        os.Exit(1)
    }

    secretsClient, err := secrets.NewSecretsClientWithConfigurationProvider(authProvider)
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Initializing OCI Secrets Client: %v\n", err)
        os.Exit(1)
    }

    secretName := fmt.Sprintf("aid-key-%x", spiffeid.Hash(agentURN))
    getSecretReq := secrets.GetSecretBundleByNameRequest{
        VaultId:    &vaultOCID,
        SecretName: &secretName,
    }

    var privateKeyBytes []byte
    secretBundle, err := secretsClient.GetSecretBundleByName(ctx, getSecretReq)
    if err == nil {
        // Secret exists, extract base64-encoded PEM
        base64Data := secretBundle.SecretBundleContent.(secrets.Base64SecretBundleContentDetails)
        rawKeyPEM, err := base64.StdEncoding.DecodeString(*base64Data.Content)
        if err != nil {
            fmt.Fprintf(os.Stderr, "FATAL: Failed decoding key payload from Vault: %v\n", err)
            os.Exit(1)
        }
        block, _ := pem.Decode(rawKeyPEM)
        parsedKey, err := x509.ParsePKCS8PrivateKey(block.Bytes)
        if err != nil {
            fmt.Fprintf(os.Stderr, "FATAL: Failed parsing retrieved private key: %v\n", err)
            os.Exit(1)
        }
        privateKeyBytes = parsedKey.(ed25519.PrivateKey)
    } else {
        // 4. Genesis Event: Generate Ed25519 keypair and persist to OCI Vault
        pubKey, privKey, err := ed25519.GenerateKey(rand.Reader)
        if err != nil {
            fmt.Fprintf(os.Stderr, "FATAL: Keypair generation failed: %v\n", err)
            os.Exit(1)
        }
        privateKeyBytes = privKey

        pkcs8Bytes, err := x509.MarshalPKCS8PrivateKey(privKey)
        if err != nil {
            fmt.Fprintf(os.Stderr, "FATAL: PKCS8 marshaling error: %v\n", err)
            os.Exit(1)
        }
        pemBlock := &pem.Block{Type: "PRIVATE KEY", Bytes: pkcs8Bytes}
        encodedPEM := base64.StdEncoding.EncodeToString(pem.EncodeToMemory(pemBlock))

        createSecretReq := vault.CreateSecretRequest{
            CreateSecretDetails: vault.CreateSecretDetails{
                CompartmentId: &compartmentOCID,
                VaultId:       &vaultOCID,
                SecretName:    &secretName,
                SecretContent: vault.Base64SecretContentDetails{
                    Content: &encodedPEM,
                },
                Description: common.String(fmt.Sprintf("Ed25519 persistent key for agent %s", agentURN)),
            },
        }
        if _, err := vaultClient.CreateSecret(ctx, createSecretReq); err != nil {
            fmt.Fprintf(os.Stderr, "FATAL: Failed saving new agent private key to OCI Vault: %v\n", err)
            os.Exit(1)
        }
        _ = pubKey // Public key persists naturally via registration in DB
    }

    // 5. Mount to In-Memory tmpfs with Strict Permissions (0400)
    if err := os.MkdirAll(filepath.Dir(outputKeyPath), 0700); err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Creating target secrets directory: %v\n", err)
        os.Exit(1)
    }

    pkcs8Data, err := x509.MarshalPKCS8PrivateKey(privateKeyBytes)
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Failed serializing private key: %v\n", err)
        os.Exit(1)
    }
    finalPEM := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: pkcs8Data})

    if err := os.WriteFile(outputKeyPath, finalPEM, 0400); err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Injecting key into tmpfs volume: %v\n", err)
        os.Exit(1)
    }

    fmt.Printf("BOOTSTRAP_COMPLETE: Identity %s authenticated and hydrated into %s\n", agentURN, outputKeyPath)
}
