Layer 3: Elpis Cryptographic Signing Sidecar Proxy
This Go sidecar runs at 127.0.0.1:8080 in the pod. The untrusted agent container cannot reach external networks directly; all outbound traffic is routed to this proxy. The proxy validates the payload, reads the isolated Ed25519 private key from the memory-backed tmpfs, signs the request envelope, and emits immutable verification headers.

Go
// cmd/elpis-proxy/main.go
package main

import (
    "bytes"
    "crypto/ed25519"
    "crypto/sha256"
    "crypto/x509"
    "encoding/base64"
    "encoding/hex"
    "encoding/pem"
    "fmt"
    "io"
    "net/http"
    "net/http/httputil"
    "net/url"
    "os"
    "strconv"
    "time"
)

type SigningProxy struct {
    privateKey ed25519.PrivateKey
    agentURN   string
    sessionID  string
    targetURL  *url.URL
    reverse    *httputil.ReverseProxy
}

func NewSigningProxy(keyPath, agentURN, sessionID, targetHost string) (*SigningProxy, error) {
    keyPEM, err := os.ReadFile(keyPath)
    if err != nil {
        return nil, fmt.Errorf("reading private key from memory mount: %w", err)
    }

    block, _ := pem.Decode(keyPEM)
    if block == nil {
        return nil, fmt.Errorf("failed decoding PEM block from key file")
    }

    parsedKey, err := x509.ParsePKCS8PrivateKey(block.Bytes)
    if err != nil {
        return nil, fmt.Errorf("failed to parse PKCS8 private key: %w", err)
    }

    privKey, ok := parsedKey.(ed25519.PrivateKey)
    if !ok {
        return nil, fmt.Errorf("key in %s is not a valid Ed25519 private key", keyPath)
    }

    target, err := url.Parse(targetHost)
    if err != nil {
        return nil, fmt.Errorf("invalid upstream URL: %w", err)
    }

    p := &SigningProxy{
        privateKey: privKey,
        agentURN:   agentURN,
        sessionID:  sessionID,
        targetURL:  target,
    }

    p.reverse = &httputil.ReverseProxy{
        Director: func(req *http.Request) {
            req.URL.Scheme = target.Scheme
            req.URL.Host = target.Host
            req.Host = target.Host
        },
    }

    return p, nil
}

func (p *SigningProxy) ServeHTTP(w http.ResponseWriter, r *http.Request) {
    bodyBytes, err := io.ReadAll(r.Body)
    if err != nil {
        http.Error(w, `{"error":"FAILED_READING_PAYLOAD"}`, http.StatusBadRequest)
        return
    }
    r.Body = io.NopCloser(bytes.NewBuffer(bodyBytes))

    // Canonical payload hash calculation
    hasher := sha256.New()
    hasher.Write(bodyBytes)
    bodyDigest := hex.EncodeToString(hasher.Sum(nil))

    timestamp := strconv.FormatInt(time.Now().Unix(), 10)

    // Canonical String to Sign (Method + URI + Timestamp + BodyHash + AgentURN + SessionID)
    canonicalString := fmt.Sprintf("%s\n%s\n%s\n%s\n%s\n%s",
        r.Method,
        r.URL.RequestURI(),
        timestamp,
        bodyDigest,
        p.agentURN,
        p.sessionID,
    )

    signature := ed25519.Sign(p.privateKey, []byte(canonicalString))
    signatureB64 := base64.StdEncoding.EncodeToString(signature)

    // Inject Attribution Envelope
    r.Header.Set("X-Agent-Id", p.agentURN)
    r.Header.Set("X-Agent-Session", p.sessionID)
    r.Header.Set("X-Agent-Timestamp", timestamp)
    r.Header.Set("X-Agent-Payload-Digest", bodyDigest)
    r.Header.Set("X-Agent-Signature", signatureB64)

    // Forward through reverse proxy
    p.reverse.ServeHTTP(w, r)
}

func main() {
    keyPath := "/run/secrets/agent-identity/ed25519.key"
    agentURN := os.Getenv("AGENT_URN")
    sessionID := os.Getenv("SESSION_ID")
    upstreamURL := os.Getenv("UPSTREAM_URL") // e.g., http://litellm-service.oke.internal:4000
    listenPort := os.Getenv("PROXY_PORT")
    if listenPort == "" {
        listenPort = "8080"
    }

    if agentURN == "" || sessionID == "" || upstreamURL == "" {
        fmt.Fprintf(os.Stderr, "FATAL: AGENT_URN, SESSION_ID, and UPSTREAM_URL must be set\n")
        os.Exit(1)
    }

    proxy, err := NewSigningProxy(keyPath, agentURN, sessionID, upstreamURL)
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Failed initializing signing proxy: %v\n", err)
        os.Exit(1)
    }

    server := &http.Server{
        Addr:         ":" + listenPort,
        Handler:      proxy,
        ReadTimeout:  120 * time.Second,
        WriteTimeout: 120 * time.Second,
    }

    fmt.Printf("ELPIS_PROXY_ONLINE: Intercepting on :%s bound to %s\n", listenPort, agentURN)
    if err := server.ListenAndServe(); err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Server exited: %v\n", err)
        os.Exit(1)
    }
}
Layer 4: DROS C-ABI Enforcement Engine (Kernel eBPF & User-Space Daemon)
This module compiles authorization scopes directly into Kernel BPF Maps and implements atomic execution termination. The eBPF program hooks the socket connection interface. If an agent process attempts an outbound connection bypassing the local proxy, or if its cancellation token is asserted, the syscall is terminated in-kernel with zero execution window.

1. The Kernel eBPF Module (dros_enforce.bpf.c)
C
// bpf/dros_enforce.bpf.c
#include "vmlinux.h"
#include 
#include 
#include 

#define EPERM 1
#define AF_INET 2

// LPM Trie map for subnets allowed for direct egress
struct ipv4_lpm_key {
    __u32 prefixlen;
    __u32 data;
};

struct {
    __uint(type, BPF_MAP_TYPE_LPM_TRIE);
    __type(key, struct ipv4_lpm_key);
    __type(value, __u8);
    __uint(max_entries, 1024);
    __uint(map_flags, BPF_F_NO_PREALLOC);
} allowed_ipv4_subnets SEC(".maps");

// Process table with real-time cancellation tokens (1 = Active, 2 = Revoked)
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __type(key, __u32);   // PID
    __type(value, __u8);  // Status
    __uint(max_entries, 32768);
} agent_process_status SEC(".maps");

// Loopback exception tracking: port 8080 (Signing Proxy) is permitted
SEC("lsm/socket_connect")
int BPF_PROG(dros_socket_connect, struct socket *sock, struct sockaddr *address, int addrlen) {
    __u64 pid_tgid = bpf_get_current_pid_tgid();
    __u32 pid = (__u32)(pid_tgid >> 32);

    // 1. Evaluate Cancellation Token Atomicity
    __u8 *status = bpf_map_lookup_elem(&agent_process_status, &pid);
    if (status) {
        if (*status == 2) {
            // Process authorization has been revoked mid-flight
            return -EPERM;
        }
    }

    if (address->sa_family != AF_INET) {
        return 0; // Allow non-IPv4 (UNIX domain sockets for SPIRE agent)
    }

    struct sockaddr_in *addr_in = (struct sockaddr_in *)address;
    __u32 dest_ip = addr_in->sin_addr.s_addr;
    __u16 dest_port = __builtin_bswap16(addr_in->sin_port);

    // 2. Allow pod-local loopback proxy connection (127.0.0.1:8080)
    if (dest_ip == 0x0100007F && dest_port == 8080) {
        return 0;
    }

    // 3. If process is marked as an Agent Core container, block direct egress
    if (status && *status == 1) {
        struct ipv4_lpm_key key = {
            .prefixlen = 32,
            .data = dest_ip,
        };
        __u8 *allowed = bpf_map_lookup_elem(&allowed_ipv4_subnets, &key);
        if (!allowed) {
            // Unregistered egress route bypassing proxy - Immediate Deny
            return -EPERM;
        }
    }

    return 0;
}

