2. The User-Space Control Daemon (main.go)
Go
// cmd/dros-daemon/main.go
package main

import (
    "context"
    "encoding/binary"
    "fmt"
    "net"
    "net/http"
    "os"
    "os/signal"
    "strconv"
    "syscall"

    "github.com/cilium/ebpf"
    "github.com/cilium/ebpf/link"
    "github.com/cilium/ebpf/rlimit"
)

// Matches the C structs
type IPV4LPMKey struct {
    PrefixLen uint32
    Data      uint32
}

func main() {
    if err := rlimit.RemoveMemlock(); err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Removing memory locks: %v\n", err)
        os.Exit(1)
    }

    spec, err := ebpf.LoadCollectionSpec("/opt/dros/dros_enforce.bpf.o")
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Failed reading BPF bytecode: %v\n", err)
        os.Exit(1)
    }

    coll, err := ebpf.NewCollection(spec)
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Loading BPF maps into kernel: %v\n", err)
        os.Exit(1)
    }
    defer coll.Close()

    // Attach to Kernel LSM Hook
    l, err := link.AttachLSM(link.LSMOptions{
        Program: coll.Programs["dros_socket_connect"],
    })
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Attaching to LSM hook (requires kernel CONFIG_BPF_LSM): %v\n", err)
        os.Exit(1)
    }
    defer l.Close()

    agentMap := coll.Maps["agent_process_status"]

    // Expose Unix Management Socket for instantaneous agent registration / revocation
    socketPath := "/var/run/dros/control.sock"
    _ = os.Remove(socketPath)

    listener, err := net.Listen("unix", socketPath)
    if err != nil {
        fmt.Fprintf(os.Stderr, "FATAL: Opening management socket: %v\n", err)
        os.Exit(1)
    }
    defer listener.Close()
    _ = os.Chmod(socketPath, 0600)

    mux := http.NewServeMux()

    // Register Agent PID
    mux.HandleFunc("/register", func(w http.ResponseWriter, r *http.Request) {
        pidStr := r.URL.Query().Get("pid")
        pid, err := strconv.ParseUint(pidStr, 10, 32)
        if err != nil {
            http.Error(w, "invalid pid", http.StatusBadRequest)
            return
        }
        p := uint32(pid)
        status := uint8(1) // Active
        if err := agentMap.Put(&p, &status); err != nil {
            http.Error(w, "bpf map error", http.StatusInternalServerError)
            return
        }
        w.WriteHeader(http.StatusOK)
        _, _ = w.Write([]byte("REGISTERED"))
    })

    // Revoke Agent PID (Immediate In-Kernel Revocation)
    mux.HandleFunc("/revoke", func(w http.ResponseWriter, r *http.Request) {
        pidStr := r.URL.Query().Get("pid")
        pid, err := strconv.ParseUint(pidStr, 10, 32)
        if err != nil {
            http.Error(w, "invalid pid", http.StatusBadRequest)
            return
        }
        p := uint32(pid)
        status := uint8(2) // Revoked Token
        if err := agentMap.Put(&p, &status); err != nil {
            http.Error(w, "bpf map error", http.StatusInternalServerError)
            return
        }
        w.WriteHeader(http.StatusOK)
        _, _ = w.Write([]byte("REVOKED"))
    })

    server := &http.Server{Handler: mux}
    go func() {
        _ = server.Serve(listener)
    }()

    fmt.Println("DROS_ENFORCER_ACTIVE: Kernel hooks locked to socket_connect via BPF LSM")

    sigChan := make(chan os.Signal, 1)
    signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
    <-sigChan

    _ = server.Shutdown(context.Background())
}

func parseIPv4ToUint32(ipStr string) uint32 {
    ip := net.ParseIP(ipStr).To4()
    if ip == nil {
        return 0
    }
    return binary.LittleEndian.Uint32(ip)
}
