TypeScript
// backstage/packages/app/src/modules/home/useEstateVoice.ts

// Add a helper to detect the platform from the User-Agent
function getDeviceMicrophoneInstructions(): string {
  if (typeof window === 'undefined' || !window.navigator) {
    return 'microphone blocked: check your browser settings';
  }

  const ua = window.navigator.userAgent.toLowerCase();

  // iOS (iPhone, iPod, iPad on newer iOS versions which claim to be Macintosh but have touch points)
  const isIOS = /iphone|ipad|ipod/.test(ua) || 
               (ua.includes('macintosh') && navigator.maxTouchPoints > 1);

  // Android
  const isAndroid = /android/.test(ua);

  if (isIOS) {
    return 'Microphone blocked. Open Settings → Safari → Microphone and select Ask or Allow.';
  } else if (isAndroid) {
    return 'Microphone blocked. Tap the lock icon in the address bar, select Permissions, and allow the microphone.';
  } else {
    // Desktop Fallback (macOS / Windows)
    return 'microphone blocked by macOS, not the site — System Settings → Privacy & Security → Microphone → turn Chrome ON…';
  }
}

// Update micRefusalDetail to use the helper
async function micRefusalDetail(): Promise {
  const blocked = await micBlocker();
  if (blocked) return blocked;

  // Return the device-appropriate instruction
  return getDeviceMicrophoneInstructions();
}

// Update micBlocker to ensure its "denied" branch also uses the helper
async function micBlocker(): Promise {
  if (!isSecureContext) {
    return 'unavailable: this page is not on https';
  }

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    // Device-not-found branch
    return 'No microphone found: check this device has one and no other app is holding it.'; 
  }

  try {
     const status = await navigator.permissions.query({ name: 'microphone' as PermissionName });
     if (status.state === 'denied') {
        // Use the device-aware helper instead of the hardcoded padlock/chrome://settings message
        return getDeviceMicrophoneInstructions();
     }
  } catch (e) {
     // permissions query not supported (e.g. Safari), continue
  }

  return null;
}
